UPDATE seal.consent_template
   SET template_name = #{templateName}, updated_by = #{actorId}, updated_at = #{now},
       version_no = version_no + 1
 WHERE consent_template_id = #{templateId}
   AND version_no = #{versionNo}

UPDATE seal.consent_template_version
   SET workflow_status = 'RETIRED', updated_by = #{actorId}, updated_at = #{now},
       version_no = version_no + 1
 WHERE consent_template_id = #{templateId}
   AND consent_template_version_id <> #{newVersionId}
   AND workflow_status = 'PUBLISHED'

mapper.select:
SELECT EXISTS (
    SELECT 1 FROM seal.consent_template_version candidate
     WHERE candidate.consent_template_id = #{templateId}
       AND candidate.consent_template_version_id = #{sourceVersionId}
       AND candidate.workflow_status IN ('PUBLISHED', 'RETIRED')
       AND candidate.version_number = (
           SELECT max(latest.version_number)
             FROM seal.consent_template_version latest
            WHERE latest.consent_template_id = #{templateId}
              AND latest.workflow_status IN ('PUBLISHED', 'RETIRED')
       )
)

SELECT COALESCE(max(version_number), 0) + 1
  FROM seal.consent_template_version
 WHERE consent_template_id = #{templateId}

