UPDATE seal.consent_template SET deleted_at = #{now}, deleted_by = #{actorId}, delete_reason = #{reason}, updated_by = #{actorId}, updated_at = #{now}, version_no = consent_template.version_no + 1 FROM seal.processing_activity activity, visible_scope scope WHERE consent_template.consent_template_id IN
#{templateId}
AND consent_template.deleted_at IS NULL AND activity.processing_activity_id = consent_template.processing_activity_id AND scope.organization_unit_id = activity.owner_organization_unit_id

UPDATE seal.consent_template SET deleted_at = NULL, deleted_by = NULL, delete_reason = NULL, updated_by = #{actorId}, updated_at = #{now}, version_no = consent_template.version_no + 1 FROM seal.processing_activity activity, visible_scope scope WHERE consent_template.consent_template_id IN
#{templateId}
AND consent_template.deleted_at IS NOT NULL AND activity.processing_activity_id = consent_template.processing_activity_id AND scope.organization_unit_id = activity.owner_organization_unit_id
